export const PRIMITIVES_CSS = "/* Shared functional controls. Surface-specific layout belongs with the surface. */\n:root { container-type: inline-size; }\n*, *::before, *::after { box-sizing: border-box; }\nhtml, body { background: var(--mp-surface-canvas); color: var(--mp-text-primary); }\nbody { font-family: var(--mp-font-ui); line-height: var(--mp-line-ui); }\nbutton, input, textarea, select { font: inherit; color: inherit; }\nbutton, [role=\"button\"], summary, input, select { min-height: var(--mp-control-minimum); }\nbutton, [role=\"button\"] { min-width: var(--mp-control-minimum); }\nbutton, input, textarea, select { border-color: var(--mp-border-control); }\ninput, textarea, select { background: var(--mp-surface-input); color: var(--mp-text-primary); }\ninput::placeholder, textarea::placeholder { color: var(--mp-text-placeholder); opacity: 1; }\nbutton { cursor: pointer; }\nbutton:disabled { cursor: default; }\na { color: var(--mp-text-link); }\n:is(button, a, input, textarea, select, summary, [tabindex]):focus-visible {\n  outline: 2px solid var(--mp-focus-ring) !important;\n  outline-offset: 2px !important;\n}\nbutton:active:not(:disabled), [role=\"button\"]:active { background: var(--mp-surface-pressed); }\nbutton.primary:is(:hover, :active), .btn.primary:is(:hover, :active), .btn.follow:is(:hover, :active) { background: var(--mp-action-primary); color: var(--mp-action-on-primary); filter: none; }\nbutton.danger:is(:hover, :active) { background: var(--mp-action-danger); color: var(--mp-action-on-danger); }\n[aria-busy=\"true\"] { cursor: progress; }\n@media (pointer: coarse) {\n  :root { --mp-control-height: var(--mp-control-touch); --mp-control-minimum: var(--mp-control-touch); }\n}\n@media (prefers-contrast: more) {\n  :root { --mp-text-secondary: var(--mp-text-primary) !important; --mp-text-placeholder: var(--mp-text-primary) !important; --mp-border-control: var(--mp-text-primary) !important; }\n}\n@media (forced-colors: active) {\n  :root {\n    --mp-surface-canvas: Canvas !important; --mp-surface-card: Canvas !important; --mp-surface-inset: Canvas !important;\n    --mp-surface-raised: Canvas !important; --mp-surface-input: Canvas !important; --mp-surface-hover: Canvas !important;\n    --mp-surface-selected: Canvas !important; --mp-surface-pressed: Canvas !important;\n    --mp-text-primary: CanvasText !important; --mp-text-secondary: CanvasText !important; --mp-text-placeholder: CanvasText !important;\n    --mp-text-link: LinkText !important; --mp-border-control: ButtonText !important; --mp-border-divider: CanvasText !important;\n    --mp-action-primary: ButtonText !important; --mp-action-on-primary: ButtonFace !important; --mp-focus-ring: Highlight !important;\n  }\n  [aria-pressed=\"true\"], .current { outline: 2px solid Highlight; outline-offset: -3px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: 0s !important; animation-duration: 0s !important; }\n}\n";
